<script setup>
import {ref,computed,onMounted,onBeforeUnmount,watch,nextTick} from 'vue';
import {state,t,go,api,brandLogo,notify,human,testTypeCode,testTypeName,toggleLanguage} from '../store';
import Icon from './Icon.vue';
import TextSizeControl from './TextSizeControl.vue';
import QuestionRenderer from './QuestionRenderer.vue';
const id=state.path.split('/')[2],payload=ref(null),loading=ref(true),error=ref(''),index=ref(0),answers=ref({}),marked=ref({}),dirty=ref({}),saving=ref(false),online=ref(navigator.onLine),remaining=ref(0),submitting=ref(false),showSubmit=ref(false),showGrid=ref(false),full=ref(!!document.fullscreenElement),submitted=ref(false),responseBusy=ref(false),now=ref(Date.now()),questionTiming=ref({}),activationPending=ref(false),activated=ref({}),rejectedEdits=ref({}),blockedAnswers=ref({});
const examHeader=ref(null),examSidebar=ref(null),submitDialog=ref(null),headerHeight=ref(96);const questionNavigationMedia=matchMedia('(max-width: 800px)'),mobileQuestionNavigation=ref(questionNavigationMedia.matches);let headerObserver,returnFocus,examOverflow='';
let tick,saveTimeout,deadline=0,serverOffset=0,flushPromise=null,autoSubmitAttempted=false,revision=Date.now();const key='inbaf-attempt-'+id;
const questions=computed(()=>payload.value?.sections?.flatMap((s,si)=>(s.questions||[]).map(q=>({...q,section_id:s.id,section_title:s.title,section_index:si,section_start:s.starts_at,section_end:s.ends_at})))||[]);
const timerEnabled=computed(()=>payload.value?.rules?.timer_enabled!==false);
const monitored=computed(()=>payload.value?.rules?.security_monitoring===true);
const typeCode=computed(()=>testTypeCode(payload.value?.attempt));
const current=computed(()=>questions.value[index.value]),answered=computed(()=>questions.value.filter(q=>hasAnswer(answers.value[q.key])).length);
const timer=computed(()=>{let value=Math.max(0,remaining.value);return[Math.floor(value/3600),Math.floor(value%3600/60),value%60].map(n=>String(n).padStart(2,'0')).join(':')});
const sectionRemaining=computed(()=>{const seconds=Math.max(0,Math.ceil((new Date(current.value?.section_end).getTime()-now.value-serverOffset)/1000));return Number.isFinite(seconds)?Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0'):''});
const questionExpired=computed(()=>!!current.value&&isQuestionExpired(current.value.key));
const questionRemaining=computed(()=>{if(!timerEnabled.value)return null;const at=questionTiming.value[current.value?.key]?.expires;if(!at)return null;return Math.max(0,Math.ceil((new Date(at).getTime()-now.value-serverOffset)/1000))});
const syncText=computed(()=>!online.value?t('offline'):Object.keys(blockedAnswers.value).length?'Some responses need attention':saving.value||Object.keys(dirty.value).length?t('syncing'):t('connected'));
function hasAnswer(v){return v!==undefined&&v!==null&&v!==''&&(Array.isArray(v)?v.length>0:typeof v==='object'?Object.keys(v).length>0:true)}
function storeLocal(){try{localStorage.setItem(key,JSON.stringify({answers:answers.value,marked:marked.value,dirty:dirty.value,index:index.value,at:Date.now()}))}catch(e){notify('Device storage is unavailable. Keep your connection active.',true)}}
function update(value){if(!current.value||submitting.value||!canRespond(current.value))return;answers.value[current.value.key]=value;delete blockedAnswers.value[current.value.key];dirty.value[current.value.key]=++revision;storeLocal();clearTimeout(saveTimeout);if(questionRemaining.value!==null&&questionRemaining.value<=3)flush();else saveTimeout=setTimeout(flush,450)}
function toggleMark(){if(!current.value||!canRespond(current.value))return;marked.value[current.value.key]=!marked.value[current.value.key];dirty.value[current.value.key]=++revision;storeLocal();flush()}
function flush(){if(flushPromise)return flushPromise;flushPromise=performFlush().finally(()=>flushPromise=null);return flushPromise}
async function performFlush(){
 if(saving.value||!online.value||submitted.value)return;
 saving.value=true;
 for(const [question_key,stamp] of Object.entries({...dirty.value})){
  if(blockedAnswers.value[question_key])continue;
  const queuedQuestion=questions.value.find(q=>q.key===question_key);
  if(payload.value?.rules?.lock_sections!==false&&queuedQuestion?.section_start&&now.value+serverOffset<new Date(queuedQuestion.section_start).getTime())continue;
  try{
   await api('/attempts/'+id+'/answers',{method:'PUT',body:{question_key,response:answers.value[question_key]??null,marked:!!marked.value[question_key]}});
   if(dirty.value[question_key]===stamp)delete dirty.value[question_key];
   storeLocal();
  }catch(e){
   const question=questions.value.find(q=>q.key===question_key);
   const sectionClosed=payload.value?.rules?.lock_sections!==false&&question?.section_end&&now.value+serverOffset>=new Date(question.section_end).getTime();
   if(['question_expired','section_closed'].includes(e.data?.code)||(e.status===422&&sectionClosed)){
    const expired=e.data?.expired_question_key||question_key;
    if(e.data?.code==='question_expired')questionTiming.value[expired]={...(questionTiming.value[expired]||{}),expires:e.data.question_expires_at||new Date(now.value+serverOffset-1).toISOString()};
    let accepted=e.data?.answer;
    if(!accepted){try{accepted=(await api('/attempts/'+id)).answers?.[expired]}catch(recoveryError){}}
    if(accepted){rejectedEdits.value[expired]=answers.value[expired];answers.value[expired]=accepted.response??null;marked.value[expired]=!!accepted.marked}
    delete dirty.value[expired];delete blockedAnswers.value[expired];storeLocal();
    if(current.value?.key===expired)error.value=e.message;
    continue;
   }
   if(e.data?.code==='section_not_started')continue;
   error.value=e.message;
   if(e.status===422){blockedAnswers.value[question_key]=e.message;continue}
   break;
  }
 }
 saving.value=false;
}
async function load(){try{payload.value=await api('/attempts/'+id);if(payload.value.attempt.status!=='in_progress'){submitted.value=true;go('/results/'+id);return}const raw=payload.value.answers||{};for(const [k,v] of Object.entries(raw)){answers.value[k]=v?.response!==undefined?v.response:v;marked.value[k]=!!v?.marked;if(v?.question_started_at){activated.value[k]=true;questionTiming.value[k]={starts:v.question_started_at,expires:v.question_expires_at}}}let local=null;try{local=JSON.parse(localStorage.getItem(key)||'null')}catch(e){notify('Recovery data could not be read. Server-saved answers have been restored.',true)};if(local){for(const k of Object.keys(local.dirty||{})){answers.value[k]=local.answers[k];marked.value[k]=local.marked[k];dirty.value[k]=local.dirty[k];revision=Math.max(revision,Number(local.dirty[k])||0)}index.value=Math.min(local.index||0,Math.max(0,questions.value.length-1))}serverOffset=new Date(payload.value.server_time).getTime()-Date.now();if(!Number.isFinite(serverOffset))serverOffset=0;deadline=!timerEnabled.value?0:payload.value.attempt.expires_at?new Date(payload.value.attempt.expires_at).getTime()-serverOffset:Date.now()+Number(payload.value.attempt.remaining_seconds)*1000;remaining.value=timerEnabled.value?Math.max(0,Math.ceil((deadline-Date.now())/1000)):0;if(current.value&&!sectionAccess(current.value)){const available=questions.value.findIndex(sectionAccess);if(available>=0)index.value=available}await flush()}catch(e){error.value=e.message}finally{loading.value=false}}
async function submit(force=false){if(submitting.value||submitted.value)return;if(responseBusy.value&&!force){notify('Finish recording and wait for the upload before submitting.',true);return}submitting.value=true;error.value='';try{await flush();if(Object.keys(dirty.value).length&&!force)throw new Error('Some answers are still waiting to sync. Check your connection and try again.');const result=await api('/attempts/'+id+'/submit',{method:'POST'});submitted.value=true;localStorage.removeItem(key);if(document.fullscreenElement)await document.exitFullscreen().catch(()=>{});notify(t('examComplete'));go('/results/'+(result.attempt?.id||result.id||id))}catch(e){error.value=e.message;showSubmit.value=true}finally{submitting.value=false}}
function isQuestionExpired(key){if(!timerEnabled.value)return false;const expiry=questionTiming.value[key]?.expires;return !!expiry&&now.value+serverOffset>=new Date(expiry).getTime()}
function canRespond(q){return !!q&&sectionAccess(q)&&!isQuestionExpired(q.key)&&(!timerEnabled.value||!q.duration_seconds||activated.value[q.key])&&!activationPending.value}
async function activateQuestion(q){if(!q||!sectionAccess(q)||activated.value[q.key]||activationPending.value)return;if(!online.value){if(q.duration_seconds)error.value='Reconnect to activate this timed question.';return}activationPending.value=true;try{const result=await api('/attempts/'+id+'/questions/'+encodeURIComponent(q.key)+'/activate',{method:'POST',body:{}});questionTiming.value[q.key]={starts:result.question_started_at||result.answer?.question_started_at,expires:result.question_expires_at||result.answer?.question_expires_at};activated.value[q.key]=true}catch(e){error.value=e.message}finally{activationPending.value=false;if(current.value?.key!==q.key)activateQuestion(current.value)}}
function sectionAccess(q){if(!q||!timerEnabled.value||payload.value?.rules?.lock_sections===false)return true;const time=now.value+serverOffset;return (!q.section_start||time>=new Date(q.section_start).getTime())&&(!q.section_end||time<new Date(q.section_end).getTime())}
function navigate(i){if(activationPending.value)return;if(i<0||i>=questions.value.length)return;if(!sectionAccess(questions.value[i])){notify('This section is outside its assigned time. Please wait for its scheduled opening.',true);return}if(responseBusy.value){notify('Finish your recording and wait for the upload before moving on.',true);return}index.value=Math.max(0,Math.min(i,questions.value.length-1));showGrid.value=false;storeLocal();flush();window.scrollTo({top:0,behavior:'instant'})}
async function event(type,metadata={}){if(!payload.value||submitted.value||!monitored.value)return;try{const result=await api('/attempts/'+id+'/events',{method:'POST',body:{type,metadata}});if(type==='tab_hidden'&&result.recorded){const count=result.tab_switch_count,limit=result.tab_switch_limit;error.value=state.language==='id'?'Perpindahan tab tercatat: '+count+(limit?' dari batas '+limit:'')+'. '+(result.limit_exceeded?'Batas terlampaui. Aktivitas ini akan ditinjau oleh pengelola.':'Tetap di jendela ujian.'): 'Tab changes recorded: '+count+(limit?' of '+limit:'')+'. '+(result.limit_exceeded?'The limit has been exceeded. The institution will review this activity.':'Please remain in the assessment window.')}}catch(e){}}
function visibility(){if(monitored.value&&document.hidden)event('tab_hidden',{question_key:current.value?.key})}
function fullchange(){full.value=!!document.fullscreenElement;if(monitored.value&&!full.value)event('fullscreen_exit')}
async function toggleFullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch(e){notify(e.message,true)}}
function connection(){online.value=navigator.onLine;event(online.value?'connection_restored':'connection_lost');if(online.value){activateQuestion(current.value).then(flush)}}
function unload(e){if(!submitted.value&&payload.value){storeLocal();e.preventDefault();e.returnValue=''}}
function questionNavigationChanged(event){mobileQuestionNavigation.value=event.matches;if(!event.matches)showGrid.value=false}
function keyboard(e){
 const target=showSubmit.value?submitDialog.value:showGrid.value?examSidebar.value:null;
 if(!target)return;
 if(e.key==='Escape'){e.preventDefault();if(showSubmit.value&&!submitting.value)showSubmit.value=false;else if(!showSubmit.value)showGrid.value=false;return}
 if(e.key!=='Tab')return;
 const items=[...target.querySelectorAll('button:not([disabled]),a[href],input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex="0"]')].filter(item=>item.getClientRects().length);
 if(!items.length){e.preventDefault();target.focus();return}
 const first=items[0],last=items[items.length-1];
 if(e.shiftKey&&(document.activeElement===first||!target.contains(document.activeElement))){e.preventDefault();last.focus()}else if(!e.shiftKey&&(document.activeElement===last||!target.contains(document.activeElement))){e.preventDefault();first.focus()}
}
watch([showSubmit,showGrid],async([submitOpen,gridOpen],[wasSubmit,wasGrid])=>{if(submitOpen||gridOpen){if(!wasSubmit&&!wasGrid){returnFocus=document.activeElement;examOverflow=document.body.style.overflow;document.body.style.overflow='hidden'}await nextTick();const target=submitOpen?submitDialog.value:examSidebar.value;target?.querySelector('button:not([disabled])')?.focus()}else{document.body.style.overflow=examOverflow;await nextTick();returnFocus?.focus();returnFocus=null}});
watch(()=>current.value?.key,()=>{if(!loading.value)activateQuestion(current.value)});
onMounted(async()=>{headerObserver=new ResizeObserver(()=>{headerHeight.value=Math.ceil(examHeader.value?.getBoundingClientRect().height||96)});if(examHeader.value)headerObserver.observe(examHeader.value);document.addEventListener('keydown',keyboard);questionNavigationMedia.addEventListener('change',questionNavigationChanged);await load();await activateQuestion(current.value);tick=setInterval(()=>{now.value=Date.now();remaining.value=timerEnabled.value?Math.max(0,Math.ceil((deadline-Date.now())/1000)):0;if(timerEnabled.value&&remaining.value<=0&&payload.value&&!submitting.value&&!submitted.value&&!autoSubmitAttempted){autoSubmitAttempted=true;submit(true)}else if(Object.keys(dirty.value).length)flush();if(current.value&&!sectionAccess(current.value)&&!responseBusy.value){const available=questions.value.findIndex(sectionAccess);if(available>=0)index.value=available}},1000);addEventListener('online',connection);addEventListener('offline',connection);addEventListener('beforeunload',unload);document.addEventListener('visibilitychange',visibility);document.addEventListener('fullscreenchange',fullchange)});
onBeforeUnmount(()=>{headerObserver?.disconnect();questionNavigationMedia.removeEventListener('change',questionNavigationChanged);if(showSubmit.value||showGrid.value)document.body.style.overflow=examOverflow;document.removeEventListener('keydown',keyboard);clearInterval(tick);clearTimeout(saveTimeout);removeEventListener('online',connection);removeEventListener('offline',connection);removeEventListener('beforeunload',unload);document.removeEventListener('visibilitychange',visibility);document.removeEventListener('fullscreenchange',fullchange)});
</script>
<template><div class="exam-shell" :style="{'--exam-header-height':headerHeight+'px'}"><header ref="examHeader" class="exam-header" :inert="showSubmit||(mobileQuestionNavigation&&showGrid)"><img :src="brandLogo()" alt="INBAF"><span class="exam-header-divider"></span><div class="exam-header-title"><strong>{{payload?.attempt?.package?.name||payload?.attempt?.package_name||'Indonesian assessment'}}</strong><span><Icon :name="monitored?'ShieldCheck':'BookOpenCheck'" :size="16"/>{{testTypeName(typeCode)}}</span></div><TextSizeControl compact/><button class="language-button" @click="toggleLanguage" aria-label="Change language / Ganti bahasa">{{state.language.toUpperCase()}}</button><div v-if="timerEnabled" class="exam-timer" :class="{urgent:remaining<300}"><Icon name="Clock3" :size="20"/><span><small>{{t('remaining')}}</small><strong>{{timer}}</strong></span></div><span v-else class="exam-untimed badge green"><Icon name="Infinity" :size="20"/>{{t('untimed')}}</span><button class="icon-button" @click="toggleFullscreen" :aria-label="full?'Exit fullscreen':'Enter fullscreen'"><Icon :name="full?'Minimize':'Maximize'" :size="20"/></button><button class="button secondary mobile-question-toggle" @click="showGrid=!showGrid" :aria-expanded="showGrid" aria-controls="exam-question-navigation" aria-label="Question navigation / Daftar soal"><Icon name="LayoutGrid" :size="18"/></button></header><div v-if="loading" class="initial-loader"><span class="loader"></span><p>{{t('loading')}}</p></div><div v-else-if="!payload" class="panel empty-state"><p class="inline-error">{{error}}</p><button class="button" @click="load">Retry</button><button class="text-button" @click="go('/dashboard')">{{t('back')}}</button></div><div v-else class="exam-layout"><button v-if="showGrid" class="exam-navigation-backdrop" @click="showGrid=false" aria-label="Close question navigation"></button><aside ref="examSidebar" id="exam-question-navigation" class="exam-sidebar" :inert="showSubmit||(mobileQuestionNavigation&&!showGrid)" :aria-hidden="mobileQuestionNavigation&&!showGrid?true:undefined" :role="mobileQuestionNavigation&&showGrid&&!showSubmit?'dialog':undefined" :aria-modal="mobileQuestionNavigation&&showGrid&&!showSubmit?true:undefined" :aria-label="state.language==='id'?'Navigasi soal':'Question navigation'" :class="{open:showGrid}"><button class="button secondary mobile-question-toggle full" @click="showGrid=false"><Icon name="X" :size="20"/>{{state.language==='id'?'Tutup daftar soal':'Close question navigation'}}</button><div class="exam-progress-heading"><span class="eyebrow">{{t('progress')}}</span><strong>{{answered}}<small> / {{questions.length}}</small></strong><div class="progress-track"><i :style="{width:(answered/Math.max(1,questions.length)*100)+'%'}"></i></div><span>{{answered}} {{t('answered')}}</span></div><div v-for="(section,si) in payload.sections" :key="section.id" class="exam-section"><h4><span>{{String(si+1).padStart(2,'0')}}</span>{{section.title}}</h4><div class="question-number-grid"><button v-for="q in section.questions" :key="q.key" :class="{current:current?.key===q.key,answered:hasAnswer(answers[q.key]),marked:marked[q.key],invalid:!!blockedAnswers[q.key]}" :disabled="!sectionAccess({...q,section_start:section.starts_at,section_end:section.ends_at})||responseBusy||activationPending" @click="navigate(questions.findIndex(i=>i.key===q.key))" :aria-current="current?.key===q.key?'step':undefined" :aria-label="'Question '+(questions.findIndex(i=>i.key===q.key)+1)" :title="(hasAnswer(answers[q.key])?t('answered'):t('question'))+(marked[q.key]?', '+t('review'):'')">{{questions.findIndex(i=>i.key===q.key)+1}}<span v-if="marked[q.key]"></span></button></div></div><div class="exam-legend"><span><i class="legend-current"></i>{{state.language==='id'?'Aktif':'Current'}}</span><span><i class="legend-answered"></i>{{t('answered')}}</span><span><i class="legend-marked"></i>{{t('review')}}</span><span><i></i>{{state.language==='id'?'Belum dijawab':'Unanswered'}}</span></div><button class="button secondary full" @click="showSubmit=true"><Icon name="Send" :size="16"/>{{t('finish')}}</button><div class="exam-saved" :class="{offline:!online}"><Icon :name="!online?'WifiOff':saving?'RefreshCw':'CloudCheck'" :size="16"/>{{syncText}}</div></aside><main class="exam-main" :inert="showSubmit||(mobileQuestionNavigation&&showGrid)"><details class="exam-instructions"><summary><Icon name="CircleHelp" :size="20"/>Petunjuk singkat / Quick instructions</summary><div class="bilingual-instructions"><div lang="id"><h3>Bahasa Indonesia</h3><p>Baca petunjuk dan pilih atau tulis jawaban Anda. Gunakan Sebelumnya dan Berikutnya untuk berpindah soal. Tandai soal untuk diperiksa kembali sebelum mengirim. Jawaban tersimpan otomatis.</p><p>{{timerEnabled?'Perhatikan waktu yang tersisa; timer tetap berjalan saat ukuran teks diubah.':'Sesi ini tanpa hitung mundur. Anda dapat mengubah ukuran teks kapan saja.'}}</p></div><div lang="en"><h3>English</h3><p>Read the instructions and select or write your response. Use Previous and Next to move between questions. Mark questions to review before submitting. Responses save automatically.</p><p>{{timerEnabled?'Watch the remaining time. Changing text size keeps the timer running.':'This session has no countdown. You can change text size at any time.'}}</p></div></div></details><div v-if="error" class="inline-error">{{error}}<button class="text-button" @click="error='';flush()">Retry sync</button></div><template v-if="current"><div v-if="payload.rules?.require_fullscreen&&!full" class="notice-banner"><Icon name="Maximize" :size="18"/><span>This assessment uses fullscreen mode.</span><button class="text-button" @click="toggleFullscreen">Enter fullscreen</button></div><div v-if="questionExpired" class="notice-banner"><Icon name="Clock3" :size="18"/>The time for this question has ended. Only responses saved before the deadline count. Continue to the next question.</div><details v-if="questionExpired&&typeof rejectedEdits[current.key]==='string'&&rejectedEdits[current.key]" class="rejected-response"><summary>View text that arrived after the deadline</summary><p>This text was not accepted for scoring. You can select and copy it for your own reference.</p><pre>{{rejectedEdits[current.key]}}</pre></details><div v-if="activationPending" class="notice-banner"><span class="loader"></span>Activating the server timer for this question...</div><div v-if="!sectionAccess(current)" class="notice-banner"><Icon name="LockKeyhole" :size="18"/>This section is outside its assigned time. Answers are locked.</div><div class="exam-question-meta"><span class="badge blue">{{current.section_title}}</span><span>{{t('question')}} {{index+1}} {{t('of')}} {{questions.length}}</span><span class="section-countdown" v-if="timerEnabled&&payload.rules?.lock_sections&&sectionRemaining"><Icon name="Timer" :size="14"/>Section {{sectionRemaining}}</span><span v-if="questionRemaining!==null" class="question-countdown" :class="{urgent:questionRemaining<=15}"><Icon name="Clock3" :size="14"/>{{Math.floor(questionRemaining/60)}}:{{String(questionRemaining%60).padStart(2,'0')}}</span><span class="question-type-label">{{human(current.type)}}</span></div><section class="panel exam-question"><QuestionRenderer :key="current.key" :question="current" :model-value="answers[current.key]??null" @update:model-value="update" :attempt-id="id" :time-remaining="questionRemaining" :disabled="submitting||!canRespond(current)" @busy="responseBusy=$event"/></section><div class="exam-navigation"><button class="button secondary" :disabled="index===0||responseBusy||activationPending" @click="navigate(index-1)"><Icon name="ArrowLeft" :size="17"/>{{t('previous')}}</button><button class="text-button mark-button" :disabled="!canRespond(current)||submitting" :class="{isMarked:marked[current.key]}" @click="toggleMark"><Icon name="Flag" :size="17"/>{{marked[current.key]?'Marked for review':t('mark')}}</button><button v-if="index<questions.length-1" class="button" :disabled="responseBusy||activationPending||!sectionAccess(questions[index+1])" @click="navigate(index+1)">{{t('next')}}<Icon name="ArrowRight" :size="17"/></button><button v-else class="button" @click="showSubmit=true">{{t('finish')}}<Icon name="Send" :size="17"/></button></div></template><div v-else class="panel empty-state"><p>No questions were found in this assessment. Contact the administrator.</p><button class="button" @click="showSubmit=true">Finish assessment</button></div><div class="exam-bottom-note"><Icon name="CloudCheck" :size="18"/>{{state.language==='id'?'Jawaban tersimpan otomatis. Periksa jawaban sebelum mengirim.':'Responses save automatically. Review your answers before submitting.'}}</div></main></div><div v-if="showSubmit" class="modal-overlay"><section ref="submitDialog" class="modal submit-modal" tabindex="-1" role="dialog" aria-modal="true" aria-labelledby="submit-title"><span class="auth-mini-icon"><Icon name="Send" :size="27"/></span><h2 id="submit-title">Ready to close this chapter?</h2><p>{{t('confirmSubmit')}}</p><div class="submit-summary"><div><strong>{{answered}}</strong><span>{{t('answered')}}</span></div><div><strong>{{questions.length-answered}}</strong><span>Unanswered</span></div><div><strong>{{Object.values(marked).filter(Boolean).length}}</strong><span>{{t('review')}}</span></div></div><p v-if="error" class="inline-error">{{error}}</p><div class="modal-footer"><button class="button secondary" @click="showSubmit=false" :disabled="submitting">Keep going</button><button class="button" @click="submit(false)" :disabled="submitting">{{submitting?'Submitting…':t('submit')}}<Icon name="Send" :size="16"/></button></div></section></div></div></template>
